const root=document.querySelector('.shell'),robot=root.querySelector('.robot'),gaze=root.querySelector('.gaze'),trigger=root.querySelector('.trigger'),panel=root.querySelector('.panel');
const neutral='M74 105V109H86V105',happy='M72 103V110H88V103',sad='M73 112V106H87V112',focus='M74 106H86',surprise='M76 103H84V112H76Z';
const states={idle:['#facc15','#b4faff','Готов помочь',16,neutral,''],greeting:['#facc15','#b4faff','Привет!',10,happy,''],upload:['#38bdf8','#a5f3fc','Документ получен',12,happy,''],extract:['#38bdf8','#a5f3fc','Извлекаю требования',12,focus,''],thinking:['#a78bfa','#ddd6fe','Анализирую...',8,focus,'M55 79H68M91 79H104'],critical:['#f59e0b','#fde68a','Противоречие!',20,surprise,'M55 78L68 75M91 75L104 78'],verify:['#22d3ee','#a5f3fc','Проверяю доказательства',10,focus,''],report:['#818cf8','#e0e7ff','Формирую отчёт',14,neutral,''],success:['#22c55e','#bbf7d0','Отчёт готов!',10,happy,''],error:['#ef4444','#fca5a5','Ошибка выполнения',13,sad,'M55 80L68 84M91 84L104 80'],attachment:['#facc15','#b4faff','Файл прикреплён',12,happy,''],reading:['#38bdf8','#a5f3fc','Читаю вложение',10,focus,''],compare:['#a78bfa','#ddd6fe','Сравниваю документы',10,focus,'']};
function state(s){const v=states[s];root.dataset.state=s;robot.style.setProperty('--led',v[0]);robot.style.setProperty('--eye',v[1]);root.querySelector('.status').textContent=v[2];robot.querySelectorAll('.le,.re').forEach(e=>{e.setAttribute('height',v[3]);e.setAttribute('y',92-v[3]/2)});robot.querySelector('.mouth').setAttribute('d',v[4]);robot.querySelector('.brows').setAttribute('d',v[5]);robot.style.animation='none';void robot.getBoundingClientRect();robot.style.animation='';document.querySelectorAll('[data-test-state]').forEach(b=>b.classList.toggle('active',b.dataset.testState===s));}
let x=0,y=0,tx=0,ty=0,raf=0;function frame(){x+=(tx-x)*.55;y+=(ty-y)*.55;gaze.setAttribute('transform',`translate(${x.toFixed(2)} ${y.toFixed(2)})`);raf=Math.abs(tx-x)+Math.abs(ty-y)>.03?requestAnimationFrame(frame):0}function target(a,b){tx=a;ty=b;if(!raf)raf=requestAnimationFrame(frame)}root.addEventListener('pointermove',e=>{if(root.dataset.motion==='off'||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const m=gaze.parentNode.getScreenCTM();if(!m)return;const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(m.inverse()),dx=p.x-80,dy=p.y-92,d=Math.hypot(dx,dy),n=Math.max(d,1);target(dx/n*10.5*(1-Math.exp(-d/25)),dy/n*6.3*(1-Math.exp(-d/25)))});root.addEventListener('pointerleave',()=>target(0,0));
let open=false;function gesture(n){if(root.dataset.motion==='off'||matchMedia('(prefers-reduced-motion: reduce)').matches)return;robot.classList.remove('wake','ack');void robot.getBoundingClientRect();robot.classList.add(n)}robot.addEventListener('animationend',e=>{if(['activate','ack'].includes(e.animationName))robot.classList.remove('wake','ack')});function show(v){open=v;root.dataset.open=v?'yes':'no';panel.inert=!v;trigger.setAttribute('aria-expanded',String(v));if(v){gesture('wake');panel.querySelector('.close').focus()}else trigger.focus()};trigger.addEventListener('click',e=>{if(e.detail===0)show(!open);else if(e.detail===1)gesture('ack')});trigger.addEventListener('dblclick',e=>{e.preventDefault();show(!open)});panel.querySelector('.close').onclick=()=>show(false);root.querySelector('.open-explicit').onclick=()=>show(!open);root.addEventListener('keydown',e=>{if(e.key==='Escape'&&open)show(false)});
let files=[];const picker=panel.querySelector('input[type=file]'),composer=panel.querySelector('.composer'),text=panel.querySelector('textarea'),list=panel.querySelector('.attachments');function draw(){list.replaceChildren();files.forEach((f,i)=>{const chip=document.createElement('div');chip.className='chip';const label=document.createElement('span');label.textContent=f.name+' · '+Math.ceil(f.size/1024)+' KB';const b=document.createElement('button');b.type='button';b.textContent='×';b.setAttribute('aria-label','Remove '+f.name);b.onclick=()=>{files.splice(i,1);draw()};chip.append(label,b);list.append(chip)})}function add(items){for(const f of items){if(f.size<=20*1024*1024&&/\.(pdf|md|docx|xlsx|json|ya?ml|txt|csv)$/i.test(f.name)&&!files.some(a=>a.name===f.name&&a.size===f.size))files.push(f)}draw();if(files.length)state('attachment')};panel.querySelector('.attach').onclick=()=>picker.click();picker.onchange=()=>{add(picker.files);picker.value=''};composer.addEventListener('dragover',e=>e.preventDefault());composer.addEventListener('drop',e=>{e.preventDefault();add(e.dataTransfer.files)});panel.querySelectorAll('.suggestions button').forEach(b=>b.onclick=()=>{text.value=b.textContent;text.focus()});composer.onsubmit=e=>{e.preventDefault();if(!text.value.trim()&&!files.length)return;const h=panel.querySelector('.history'),q=document.createElement('div'),a=document.createElement('div');q.className='question';q.textContent=(files.length?files.map(f=>f.name).join(', ')+'\n':'')+(text.value.trim()||'Проанализируй вложения');a.className='reply';a.textContent='SPEC · Demo: '+(files.length?'Файлы выбраны локально. Содержимое не анализируется и не передаётся серверу.':'В рабочей версии ответ будет основан на проверенных источниках текущего аудита.');h.append(q,a);files=[];draw();text.value='';h.lastElementChild.scrollIntoView({block:'nearest'});state('idle')};
const labels=['Idle','Greeting','Document received','Extracting','Thinking','Contradiction','Verifying evidence','Generating report','Success','Error','Attachment received','Reading attachment','Comparing documents'];Object.keys(states).forEach((s,i)=>{const b=document.createElement('button');b.textContent=labels[i];b.dataset.testState=s;b.onclick=()=>state(s);document.querySelector('.controls').append(b)});document.querySelector('#motion').onchange=e=>{root.dataset.motion=e.target.checked?'on':'off';if(!e.target.checked){robot.classList.remove('wake','ack');target(0,0)}};state('idle');
